const SIZES = [
  { id:'s1', name:'Standard', w:450, h:400, unit:'mm', display:'450 × 400 mm' },
  { id:'s2', name:'Desk Mat', w:700, h:300, unit:'mm', display:'700 × 300 mm' },
  { id:'s3', name:'XL Desk Mat', w:900, h:400, unit:'mm', display:'900 × 400 mm' },
];

let currentSize = SIZES[0];
let uploadedImage = null;
let uploadedFileName = '';

const stages = Array.from(document.querySelectorAll('.stage'));
let canvas = stages[0];
let ctx = canvas.getContext('2d');
const sizeList = document.getElementById('sizeList');
const caption = document.getElementById('caption');
const fileInput = document.getElementById('fileInput');
const uploadTrigger = document.getElementById('uploadTrigger');
const fileNameEl = document.getElementById('fileName');
const downloadBtn = document.getElementById('downloadBtn');
const orderBtn = document.getElementById('orderBtn');
const statusMsg = document.getElementById('statusMsg');

const mouseImg = new Image();
mouseImg.src = "data:image/png;base64,";

function buildSizeList(){
  sizeList.innerHTML = '';
  SIZES.forEach(sz => {
    const el = document.createElement('div');
    el.className = 'size-opt' + (sz.id === currentSize.id ? ' active' : '');
    el.innerHTML = `<span class="name">${sz.name}</span><span class="dims">${sz.display}</span>`;
    el.addEventListener('click', () => { currentSize = sz; buildSizeList(); highlightActive(); draw(); });
    sizeList.appendChild(el);
  });
}

function highlightActive(){
  stages.forEach(c => c.classList.toggle('active', c.dataset.size === currentSize.id));
}

function stageFor(sizeId){
  return stages.find(c => c.dataset.size === sizeId);
}

function roundedRectPath(x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x+r, y);
  ctx.arcTo(x+w, y, x+w, y+h, r);
  ctx.arcTo(x+w, y+h, x, y+h, r);
  ctx.arcTo(x, y+h, x, y, r);
  ctx.arcTo(x, y, x+w, y, r);
  ctx.closePath();
}

function drawMouse(padX, padY, padW, padH, size){
  if (!mouseImg.complete || !mouseImg.naturalWidth) return;
  const mouseHmm = 95;
  const mh = mouseHmm * padH / size.h;
  const mw = mh * (mouseImg.naturalWidth / mouseImg.naturalHeight);
  const gap = 18;

  const spots = [
    { x: padX + padW + gap, y: padY + padH - mh },
    { x: padX + padW - mw,  y: padY + padH + gap },
    { x: padX - gap - mw,   y: padY + padH - mh },
  ];
  let best = spots[0];
  for (const s of spots){
    if (s.x >= 8 && s.y >= 8 && s.x + mw <= canvas.width - 8 && s.y + mh <= canvas.height - 8){
      best = s;
      break;
    }
  }

  ctx.save();
  ctx.globalAlpha = 0.92;
  ctx.drawImage(mouseImg, best.x, best.y, mw, mh);
  ctx.restore();
}

function drawStage(size){
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0,0,W,H);

  // stage background
  ctx.fillStyle = 'rgba(255,255,255,0.4)';
  ctx.fillRect(0,0,W,H);

  // fit pad box within stage, leaving margin for dimension lines
  const marginTop = 46, marginLeft = 56, marginRight = 30, marginBottom = 20;
  const boxW = W - marginLeft - marginRight;
  const boxH = H - marginTop - marginBottom;

  const ratio = size.w / size.h;
  let padW, padH;
  if (boxW / boxH > ratio){
    padH = boxH;
    padW = padH * ratio;
  } else {
    padW = boxW;
    padH = padW / ratio;
  }
  const padX = marginLeft + (boxW - padW)/2;
  const padY = marginTop + (boxH - padH)/2;
  const r = Math.min(padW, padH) * 0.045;

  // pad base / image
  ctx.save();
  roundedRectPath(padX, padY, padW, padH, r);
  ctx.clip();

  if (uploadedImage){
    const imgRatio = uploadedImage.width / uploadedImage.height;
    const padRatio = padW / padH;
    let dw, dh, dx, dy;
    if (imgRatio > padRatio){
      dh = padH; dw = dh * imgRatio;
      dx = padX - (dw - padW)/2; dy = padY;
    } else {
      dw = padW; dh = dw / imgRatio;
      dx = padX; dy = padY - (dh - padH)/2;
    }
    ctx.drawImage(uploadedImage, dx, dy, dw, dh);
  } else {
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--pad-base').trim();
    ctx.fillRect(padX, padY, padW, padH);
    // woven texture
    ctx.strokeStyle = 'rgba(255,255,255,0.035)';
    ctx.lineWidth = 1;
    for (let i = -padH; i < padW; i += 7){
      ctx.beginPath();
      ctx.moveTo(padX + i, padY);
      ctx.lineTo(padX + i + padH, padY + padH);
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(237,234,224,0.35)';
    ctx.font = '12px "Dekko", cursive';
    ctx.textAlign = 'center';
    ctx.fillText('UPLOAD ARTWORK TO PREVIEW', padX + padW/2, padY + padH/2);
  }
  ctx.restore();

  // stitched border
  ctx.save();
  roundedRectPath(padX + 7, padY + 7, padW - 14, padH - 14, Math.max(r - 5, 4));
  ctx.setLineDash([5,5]);
  ctx.lineWidth = 1.6;
  ctx.strokeStyle = 'rgba(217,164,65,0.75)';
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();

  // outer pad edge
  ctx.save();
  roundedRectPath(padX, padY, padW, padH, r);
  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.stroke();
  ctx.restore();

  // mouse size reference
  drawMouse(padX, padY, padW, padH, size);

  const accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
  const muted = getComputedStyle(document.documentElement).getPropertyValue('--muted').trim();
  ctx.strokeStyle = muted;
  ctx.fillStyle = accent;
  ctx.font = '11px "Dekko", cursive';
  ctx.lineWidth = 1;

  // top dimension line (width)
  const dimY = padY - 18;
  ctx.beginPath();
  ctx.moveTo(padX, dimY); ctx.lineTo(padX, padY - 6);
  ctx.moveTo(padX + padW, dimY); ctx.lineTo(padX + padW, padY - 6);
  ctx.moveTo(padX, dimY); ctx.lineTo(padX + padW, dimY);
  ctx.stroke();
  ctx.textAlign = 'center';
  ctx.fillText(`${size.w}${size.unit}`, padX + padW/2, dimY - 7);

  // left dimension line (height)
  const dimX = padX - 22;
  ctx.beginPath();
  ctx.moveTo(dimX, padY); ctx.lineTo(padX - 6, padY);
  ctx.moveTo(dimX, padY + padH); ctx.lineTo(padX - 6, padY + padH);
  ctx.moveTo(dimX, padY); ctx.lineTo(dimX, padY + padH);
  ctx.stroke();
  ctx.save();
  ctx.translate(dimX - 8, padY + padH/2);
  ctx.rotate(-Math.PI/2);
  ctx.textAlign = 'center';
  ctx.fillText(`${size.h}${size.unit}`, 0, 0);
  ctx.restore();
}

function draw(){
  stages.forEach(c => {
    canvas = c;
    ctx = c.getContext('2d');
    const size = SIZES.find(s => s.id === c.dataset.size);
    drawStage(size);
  });
  highlightActive();
  caption.innerHTML = `All sizes previewed — <b>${currentSize.name}</b> (${currentSize.display}) is selected for ordering.`;
}

uploadTrigger.addEventListener('click', () => fileInput.click());

fileInput.addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;
  uploadedFileName = file.name;
  fileNameEl.textContent = file.name;
  const reader = new FileReader();
  reader.onload = (ev) => {
    const img = new Image();
    img.onload = () => {
      uploadedImage = img;
      draw();
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
});

downloadBtn.addEventListener('click', () => {
  const link = document.createElement('a');
  link.download = `mousepad-proof-${currentSize.id}.png`;
  link.href = stageFor(currentSize.id).toDataURL('image/png');
  link.click();
});

let orderSeq = parseInt(localStorage.getItem('mps-order-seq') || '1000', 10);
function nextOrderId(){
  orderSeq += 1;
  localStorage.setItem('mps-order-seq', String(orderSeq));
  return 'MPS-' + orderSeq;
}
function orderFileName(orderId){
  const sizeSlug = currentSize.name.toLowerCase().replace(/\s+/g, '-');
  return `${orderId}_${sizeSlug}.png`;
}

orderBtn.addEventListener('click', () => {
  if (!uploadedImage){
    statusMsg.textContent = 'Upload artwork before placing an order.';
    statusMsg.className = 'status err';
    return;
  }
  const orderId = nextOrderId();
  const fname = orderFileName(orderId);
  const link = document.createElement('a');
  link.download = fname;
  link.href = stageFor(currentSize.id).toDataURL('image/png');
  link.click();
  statusMsg.textContent = `Order ${orderId} placed — saved as ${fname} (${currentSize.display}).`;
  statusMsg.className = 'status ok';
});

buildSizeList();
draw();
